}

// mutexSim is an event-driven single-core simulation with priority
// inheritance. Time only advances through run actions; lock, unlock and
// completion happen at a single instant. The wait-for graph maps a blocked
// task (waiter) to the owner of the mutex it is blocked on.
type mutexSim struct {
	tasks   []mutexTask
	n       int
	horizon int64

	owner   map[string]int       // mutex -> owning task
	waiters map[string][]int     // mutex -> blocked tasks
	locksOf []map[string]struct{} // task -> owned mutexes

	blockedM  []string // "" when not blocked
	blockTime []int64
	pc        []int   // next action to interpret
	runRem    []int64 // remainder of the run action at pc

	released   []bool
	completed  []bool
	executed   []int64
	completion []*int64
	eff        []int64

	order    []int // tasks sorted by (release, input index)
	nextRel  int
	segs     []mutexSegment
	current  int
	now      int64
	deadCycle []int
}

func simulateMutex(tasks []mutexTask, horizon int64) mutexResponse {
	n := len(tasks)
	s := &mutexSim{
		tasks:     tasks,
		n:         n,
		horizon:   horizon,
		owner:     make(map[string]int),
		waiters:   make(map[string][]int),
		locksOf:   make([]map[string]struct{}, n),
		blockedM:  make([]string, n),
		blockTime: make([]int64, n),
		pc:        make([]int, n),
		runRem:    make([]int64, n),
		released:  make([]bool, n),
		completed: make([]bool, n),
		executed:  make([]int64, n),
		completion: make([]*int64, n),
		eff:       make([]int64, n),
		current:   -1,
	}
	for i := range s.locksOf {
		s.locksOf[i] = make(map[string]struct{})
	}
	s.order = make([]int, n)
	for i := range s.order {
		s.order[i] = i
	}
	sort.Slice(s.order, func(a, b int) bool {
		ia, ib := s.order[a], s.order[b]
		if tasks[ia].release != tasks[ib].release {
			return tasks[ia].release < tasks[ib].release
		}
		return ia < ib
	})

	s.releaseUpTo()
	s.recompute()

	deadlocked := false
	for {
		s.releaseUpTo()
		cur := s.current
		if cur != -1 && (s.completed[cur] || s.blockedM[cur] != "") {
			s.current = -1
			cur = -1
		}
		if cur == -1 {
			best := s.pickBest()
			if best == -1 {
				// No runnable task: idle until the next release, or finish.
				if s.now >= horizon || s.nextRel >= n {
					s.now = horizon
					break
				}
				s.now = tasks[s.order[s.nextRel]].release
				continue
			}
			s.current = best
			if s.settle(best) {
				deadlocked = true
				break
			}
			if !s.runnable(best) {
				s.current = -1
				continue
			}
			cur = best
		} else {
			// A strictly higher effective priority preempts; equals never do.
			best := s.pickBest()
			if best != -1 && s.eff[best] < s.eff[cur] {
				s.current = best
				if s.settle(best) {
					deadlocked = true
					break
				}
				if !s.runnable(best) {
					s.current = -1
					continue
				}
				cur = best
			}
		}

		if s.now >= horizon {
			break
		}
		// Advance until the run completes, the horizon cuts it, or a strictly
		// higher base-priority task releases. Effective priorities are stable
		// across a run: wait edges only change while a task executes actions.
		rem := s.runRem[cur]
		length := rem
		if avail := horizon - s.now; length > avail {
			length = avail
		}
		end := s.now + length
		for k := s.nextRel; k < n; k++ {
			j := s.order[k]
			if tasks[j].priority < s.eff[cur] &&
				tasks[j].release > s.now && tasks[j].release < end {
				end = tasks[j].release
			}
		}
		s.segs = append(s.segs, mutexSegment{index: cur, start: s.now, end: end, eff: s.eff[cur]})
		delta := end - s.now
		s.executed[cur] += delta
		s.now = end
		if rem -= delta; rem > 0 {
			s.runRem[cur] = rem
		} else {
			s.runRem[cur] = 0
			s.pc[cur]++
		}
	}

	return s.buildResponse(deadlocked)
}

// settle drains the task's consecutive zero-duration actions. It stops when
// the task faces a run action, blocks, or completes. It reports whether the
// blocking action closed a wait-for cycle (deadlock).
func (s *mutexSim) settle(i int) bool {
	for {
		t := s.tasks[i]
		if s.pc[i] >= len(t.actions) {
			s.completed[i] = true
			now := s.now
			s.completion[i] = &now
			return false
		}
		a := t.actions[s.pc[i]]
		switch a.kind {
		case mutexActRun:
			if s.runRem[i] == 0 {
				s.runRem[i] = a.run
			}
			return false
		case mutexActLock:
			m := a.name
			if owner, ok := s.owner[m]; ok {
				if owner == i {
					// Ownership was granted via handoff while blocked here.
					s.pc[i]++
					continue
				}
				if cycle := s.cycleOnBlock(i, owner); cycle != nil {
					s.blockedM[i] = m
					s.blockTime[i] = s.now
					s.waiters[m] = append(s.waiters[m], i)
					s.deadCycle = cycle
					return true
				}
				s.blockedM[i] = m
				s.blockTime[i] = s.now
				s.waiters[m] = append(s.waiters[m], i)
				s.recompute()
				return false
			}
			s.owner[m] = i
			s.locksOf[i][m] = struct{}{}
			s.pc[i]++
		case mutexActUnlock:
			s.handoff(a.name, i)
			s.pc[i]++
		}
	}
}

// cycleOnBlock checks whether adding the edge waiter -> holder closes a cycle
// in the wait-for graph, and returns the cycle rotated to start at the
// earliest input-order task along the wait direction.
func (s *mutexSim) cycleOnBlock(waiter, holder int) []int {
	prev := make([]int, s.n)
	for k := range prev {
		prev[k] = -1
	}
	prev[holder] = holder
	stack := []int{holder}
	for len(stack) > 0 {
		x := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		if s.blockedM[x] == "" {
			continue
		}
		y := s.owner[s.blockedM[x]]
		if y == waiter {
			// Reverse path x .. (successor of holder), excluding holder.
			var path []int
			for cur := x; cur != holder; cur = prev[cur] {
				path = append(path, cur)
			}
			for a, b := 0, len(path)-1; a < b; a, b = a+1, b-1 {
				path[a], path[b] = path[b], path[a]
			}
			cycle := append([]int{waiter, holder}, path...)
			first := 0
			for k := 1; k < len(cycle); k++ {
				if cycle[k] < cycle[first] {
					first = k
				}
			}
			return append(append([]int(nil), cycle[first:]...), cycle[:first]...)
		}
		if prev[y] == -1 {
			prev[y] = x
			stack = append(stack, y)
		}
	}
	return nil
}

// handoff releases m from its owner and transfers it to the waiter with the
// highest effective priority, breaking ties by block time then input index.
// Effective priorities of waiters do not depend on the outgoing owner, so the
// pre-unlock values remain valid for the selection.
func (s *mutexSim) handoff(m string, from int) {
	ws := s.waiters[m]
	delete(s.locksOf[from], m)
	if len(ws) == 0 {
		delete(s.owner, m)
		s.recompute()
		return
	}
	w := ws[0]
	for _, x := range ws[1:] {
		if s.eff[x] < s.eff[w] ||
			(s.eff[x] == s.eff[w] && s.blockTime[x] < s.blockTime[w]) ||
			(s.eff[x] == s.eff[w] && s.blockTime[x] == s.blockTime[w] && x < w) {
			w = x
		}
	}
	s.owner[m] = w
	s.locksOf[w][m] = struct{}{}
	remaining := make([]int, 0, len(ws)-1)
	for _, x := range ws {
		if x != w {
			remaining = append(remaining, x)
		}
	}
	s.waiters[m] = remaining
	s.blockedM[w] = ""
	s.recompute()
}

// recompute derives every effective priority as the minimum of the task's own
// priority and the effective priorities of the direct waiters on its mutexes;
// the DFS therefore covers indirect inheritance transitively.
func (s *mutexSim) recompute() {
	mark := make([]int8, s.n)
	var dfs func(int) int64
	dfs = func(i int) int64 {
		if mark[i] == 2 {
			return s.eff[i]
		}
		mark[i] = 1
		best := s.tasks[i].priority
		for m := range s.locksOf[i] {
			for _, w := range s.waiters[m] {
				if v := dfs(w); v < best {
					best = v
				}
			}
		}
		mark[i] = 2
		s.eff[i] = best
		return best
	}
	for i := 0; i < s.n; i++ {
		dfs(i)
	}
}

// pickBest selects the runnable task with the highest effective priority,
// breaking ties by release time then input index.
func (s *mutexSim) pickBest() int {
	best := -1
	for i := 0; i < s.n; i++ {
		if !s.released[i] || s.completed[i] || s.blockedM[i] != "" {
			continue
		}
		if best == -1 {
			best = i
			continue
		}
		a, b := s.tasks[i], s.tasks[best]
		if s.eff[i] < s.eff[best] ||
			(s.eff[i] == s.eff[best] && a.release < b.release) ||
			(s.eff[i] == s.eff[best] && a.release == b.release && i < best) {
			best = i
		}
	}
	return best
}

func (s *mutexSim) runnable(i int) bool {
	return s.released[i] && !s.completed[i] && s.blockedM[i] == "" && s.runRem[i] > 0
}

func (s *mutexSim) releaseUpTo() {
	for s.nextRel < s.n && s.tasks[s.order[s.nextRel]].release <= s.now {
		s.released[s.order[s.nextRel]] = true
		s.nextRel++
	}
}

func (s *mutexSim) buildResponse(deadlocked bool) mutexResponse {
	timeline := make([]mutexTimelineInterval, 0, len(s.segs))
	for _, seg := range s.segs {
		last := len(timeline) - 1
		if last >= 0 &&
			timeline[last].TaskID == s.tasks[seg.index].id &&
			timeline[last].EffectivePriority == seg.eff &&
			timeline[last].End == seg.start {
			timeline[last].End = seg.end
			continue
		}
		timeline = append(timeline, mutexTimelineInterval{
			TaskID:            s.tasks[seg.index].id,
			Start:             seg.start,
			End:               seg.end,
			EffectivePriority: seg.eff,
		})
	}

	results := make([]mutexTaskResult, s.n)
	allCompleted := true
	for i, t := range s.tasks {
		state := "ready"
		switch {
		case s.completed[i]:
			state = "completed"
		case s.blockedM[i] != "":
			state = "blocked"
		case !s.released[i]:
			state = "unreleased"
		}
		if state != "completed" {
			allCompleted = false
		}
		var blockedOn *string
		if state == "blocked" {
			m := s.blockedM[i]
			blockedOn = &m
		}
		var deadlineStatus string
		switch c := s.completion[i]; {
		case c != nil && *c <= t.deadline:
			deadlineStatus = "met"
		case c != nil:
			deadlineStatus = "missed"
		case t.deadline <= s.horizon:
			deadlineStatus = "missed"
		default:
			deadlineStatus = "pending"
		}
		results[i] = mutexTaskResult{
			Executed:       s.executed[i],
			Completion:     s.completion[i],
			State:          state,
			BlockedOn:      blockedOn,
			DeadlineStatus: deadlineStatus,
		}
	}

	status := "horizon"
	if deadlocked {
		status = "deadlocked"
	} else if allCompleted {
		status = "completed"
	}

	resp := mutexResponse{
		Status:     status,
		Timeline:   timeline,
		Results:    results,
		DeadlockAt: nil,
		Cycle:      nil,
	}
	if deadlocked {
		at := s.now
		resp.DeadlockAt = &at
		cycle := make([]string, len(s.deadCycle))
		for k, idx := range s.deadCycle {
			cycle[k] = s.tasks[idx].id
		}
		resp.Cycle = cycle
	}
	return resp
}

