// waitSuccessors lists the blocked tasks directly waiting on mutexes owned by
// x, in input order; it fixes deterministic traversal of the wait-for graph.
func (s *mutexSim) waitSuccessors(x int) []int {
	var out []int
	for m := range s.locksOf[x] {
		out = append(out, s.waiters[m]...)
	}
	sort.Ints(out)
	return out
}

// cycleOnBlock checks whether adding the edge waiter -> holder closes a cycle
// in the wait-for graph, and returns the cycle rotated to start at the
// earliest input-order task, oriented along the wait direction.
func (s *mutexSim) cycleOnBlock(waiter, holder int) []int {
	prev := make([]int, s.n)
	for k := range prev {
		prev[k] = -1
	}
	prev[holder] = holder
	stack := []int{holder}
	found := -1
	for len(stack) > 0 {
		x := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		succ := s.waitSuccessors(x)
		// Push in reverse so the smallest index is explored first.
		for k := len(succ) - 1; k >= 0; k-- {
			y := succ[k]
			if y == waiter {
				found = x
				stack = nil
				break
			}
			if prev[y] == -1 {
				prev[y] = x
				stack = append(stack, y)
			}
		}
	}
	if found == -1 {
		return nil
	}
	var path []int
	for cur := found; cur != holder; cur = prev[cur] {
		path = append(path, cur)
	}
	for a, b := 0, len(path)-1; a < b; a, b = a+1, b-1 {
		path[a], path[b] = path[b], path[a]
	}
	cycle := append([]int{waiter, holder}, path...)
	first := 0
	for k := 1; k < len(cycle); k++ {
		if cycle[k] < cycle[first] {
			first = k
		}
	}
	return append(append([]int(nil), cycle[first:]...), cycle[:first]...)
}

