158					var ok bool
159					taskRun, ok = saturatingAdd(taskRun, *ai.Run)
160					if !ok {
161						return nil, false
162					}
163					actions = append(actions, mutexAction{kind: mutexActRun, run: *ai.Run})
164				case ai.Lock != nil:
165					name := *ai.Lock
166					if !validTaskID(name) {
167						return nil, false
168					}
169					if _, dup := held[name]; dup {
170						return nil, false
171					}
172					held[name] = struct{}{}
173					actions = append(actions, mutexAction{kind: mutexActLock, name: name})
174				default:
175					name := *ai.Unlock
176					if !validTaskID(name) {
177						return nil, false
178					}
179					if _, ok := held[name]; !ok {
180						return nil, false
181					}
182					delete(held, name)
183					actions = append(actions, mutexAction{kind: mutexActUnlock, name: name})
184				}
185			}
186			if len(held) != 0 {
187				return nil, false
188			}
189			var ok bool
190			totalRun, ok = saturatingAdd(totalRun, taskRun)
191			if !ok {
192				return nil, false
193			}
194			tasks = append(tasks, mutexTask{
195				id:       in.ID,
196				priority: *in.Priority,
197				release:  *in.Release,
198				deadline: *in.Deadline,
199				actions:  actions,
200			})
201		}
202		return tasks, true
203	}
204	
205	// mutexSegment is an unmerged run interval recorded by the simulation.
206	type mutexSegment struct {
207		index      int
208		start, end int64
209		eff        int64
210	}
211	
212	// mutexSim is an event-driven single-core simulation with priority
213	// inheritance. Time advances only through run actions; lock, unlock and
214	// completion happen at a single instant. The wait-for graph maps a blocked
215	// task (waiter) to the owner of the mutex it is blocked on.
216	type mutexSim struct {
217		tasks   []mutexTask
218		n       int
219		horizon int64
220	
221		owner   map[string]int     // mutex -> owning task
222		waiters map[string][]int   // mutex -> blocked tasks
223		locksOf []map[string]bool  // task -> owned mutexes
224	
225		blockedM  []string // "" when not blocked
226		blockTime []int64
227		pc        []int   // next action to interpret
228		runRem    []int64 // remainder of the run action at pc
229	
230		released   []bool
231		completed  []bool
232		executed   []int64
233		completion []*int64
234		eff        []int64
235	
236		order     []int // tasks sorted by (release, input index)
237		nextRel   int
238		segs      []mutexSegment
239		current   int
240		now       int64
241		deadCycle []int
242	}
243	
244	func simulateMutex(tasks []mutexTask, horizon int64) mutexResponse {
245		n := len(tasks)
246		s := &mutexSim{
247			tasks:      tasks,
248			n:          n,
249			horizon:    horizon,
250			owner:      make(map[string]int),
251			waiters:    make(map[string][]int),
252			locksOf:    make([]map[string]bool, n),
253			blockedM:   make([]string, n),
254			blockTime:  make([]int64, n),
255			pc:         make([]int, n),
256			runRem:     make([]int64, n),
257			released:   make([]bool, n),
258			completed:  make([]bool, n),
259			executed:   make([]int64, n),
260			completion: make([]*int64, n),
261			eff:        make([]int64, n),
262			current:    -1,
263		}
264		for i := range s.locksOf {
265			s.locksOf[i] = make(map[string]bool)
266			s.eff[i] = tasks[i].priority
267		}
268		s.order = make([]int, n)
269		for i := range s.order {
270			s.order[i] = i
271		}
272		sort.Slice(s.order, func(a, b int) bool {
273			ia, ib := s.order[a], s.order[b]
274			if tasks[ia].release != tasks[ib].release {
275				return tasks[ia].release < tasks[ib].release
276			}
277			return ia < ib
278		})
279	
280		deadlocked := false
281		for {
282			s.releaseUpTo()
283	
284			// After any state change, first drain the current task's consecutive
285			// zero-duration actions, then schedule.
286			if s.current != -1 {
287				if s.settle(s.current) {
288					deadlocked = true
289					break
290				}
291				if !s.runnable(s.current) {
292					s.current = -1
293				}
294			}
295	
296			if s.current == -1 {
297				best := s.pickBest()
298				if best == -1 {
299					// Nothing runnable: jump to the next release or the horizon.
300					if s.nextRel >= n {
301						s.now = horizon
302						break
303					}
304					s.now = tasks[s.order[s.nextRel]].release
305					continue
306				}
307				s.current = best
308				if s.settle(best) {
309					deadlocked = true
310					break
311				}
312				if !s.runnable(best) {
313					s.current = -1
314					continue
315				}
316			} else if best := s.pickBest(); best != -1 && s.eff[best] < s.eff[s.current] {
317				// A strictly higher effective priority preempts; equals never do.
318				s.current = best
319				if s.settle(best) {
320					deadlocked = true
321					break
322				}
323				if !s.runnable(best) {
324					s.current = -1
325					continue
326				}
327			}
328	
329			if s.now >= horizon {
330				break
331			}
332			cur := s.current
333			// Advance until the run completes, the horizon cuts it, or a strictly
334			// higher base-priority task releases. Effective priorities are stable
335			// across a run: wait edges change only via zero-duration actions.
336			rem := s.runRem[cur]
337			length := rem
338			if avail := horizon - s.now; length > avail {
339				length = avail
340			}
341			end := s.now + length
342			for k := s.nextRel; k < n; k++ {
343				j := s.order[k]
344				if tasks[j].priority < s.eff[cur] &&
345					tasks[j].release > s.now && tasks[j].release < end {
346					end = tasks[j].release
347				}
348			}
349			s.segs = append(s.segs, mutexSegment{index: cur, start: s.now, end: end, eff: s.eff[cur]})
350			delta := end - s.now
351			s.executed[cur] += delta
352			s.now = end
353			if rem -= delta; rem > 0 {
354				s.runRem[cur] = rem
355				continue
356			}
357			s.runRem[cur] = 0
358			s.pc[cur]++
359			if s.now >= horizon {
360				// The run ends exactly at the horizon: matching the one-shot
361				// baseline, completion at the boundary is observable, so drain
362				// this task's trailing zero-duration actions once. Nothing else
363				// gets to run at or past the horizon.
364				if s.settle(cur) {
365					deadlocked = true
366				}
367				break
368			}
369		}
370	
371		return s.buildResponse(deadlocked)
372	}
373	
374	// settle drains the task's consecutive zero-duration actions. It stops when
375	// the task faces a run action (arming its remainder), blocks, or completes.
376	// It reports whether the blocking action closed a wait-for cycle.
377	func (s *mutexSim) settle(i int) bool {
378		for {
379			t := s.tasks[i]
380			if s.pc[i] >= len(t.actions) {
381				s.completed[i] = true
382				now := s.now
383				s.completion[i] = &now
384				return false
385			}
386			a := t.actions[s.pc[i]]
387			switch a.kind {
388			case mutexActRun:
389				if s.runRem[i] == 0 {
390					s.runRem[i] = a.run
391				}
392				return false
393			case mutexActLock:
394				m := a.name
395				if owner, ok := s.owner[m]; ok {
396					if owner == i {
397						// Granted via handoff while blocked at this action.
398						s.pc[i]++
399						continue
400					}
401					cycle := s.cycleOnBlock(i, owner)
402					s.blockedM[i] = m
403					s.blockTime[i] = s.now
404					s.waiters[m] = append(s.waiters[m], i)
405					if cycle != nil {
406						s.deadCycle = cycle
407						return true
408					}
409					s.recompute()
410					return false
411				}
412				s.owner[m] = i
413				s.locksOf[i][m] = true
414				s.pc[i]++
415			case mutexActUnlock:
416				s.handoff(a.name, i)
417				s.pc[i]++
418			}
419		}
420	}
421	
422	// waitersOn lists the blocked tasks directly waiting on mutexes owned by x
423	// (the predecessor direction of the wait-for graph), in input order.
424	func (s *mutexSim) waitersOn(x int) []int {
425		var out []int
426		for m := range s.locksOf[x] {
427			out = append(out, s.waiters[m]...)
428		}
429		sort.Ints(out)
430		return out
431	}
432	
433	// blockTarget is the outgoing wait-for edge of x: the owner of the mutex x is
434	// blocked on, or -1 when x is not blocked.
435	func (s *mutexSim) blockTarget(x int) int {
436		if s.blockedM[x] == "" {
437			return -1
438		}
439		return s.owner[s.blockedM[x]]
440	}
441	
442	// cycleOnBlock checks whether adding the edge waiter -> holder closes a cycle
443	// in the wait-for graph. Every task has at most one outgoing edge, so the
444	// existing graph is a forest of chains (any earlier cycle would already have
445	// stopped the simulation): holder reaches waiter at most once. The returned
446	// cycle follows the wait direction and starts at the earliest input-order task.
447	func (s *mutexSim) cycleOnBlock(waiter, holder int) []int {
448		chain := []int{holder}
449		cur := holder
450		for {
451			next := s.blockTarget(cur)
452			if next == -1 {
453				return nil
454			}
455			if next == waiter {
456				break
457			}
458			chain = append(chain, next)
459			cur = next
460		}
461		cycle := append([]int{waiter}, chain...)
462		first := 0
463		for k := 1; k < len(cycle); k++ {
464			if cycle[k] < cycle[first] {
465				first = k
466			}
467		}
468		return append(append([]int(nil), cycle[first:]...), cycle[:first]...)
469	}
470	
471	// handoff releases m from its owner and transfers it to the waiter with the
472	// highest effective priority, breaking ties by block time then input index.
473	// Waiter effective priorities cannot depend on the outgoing owner's edge
474	// (waiters have no edge toward a holder of m), so the pre-unlock values stay
475	// valid for the selection.
476	func (s *mutexSim) handoff(m string, from int) {
477		ws := s.waiters[m]
478		delete(s.locksOf[from], m)
479		if len(ws) == 0 {
480			delete(s.owner, m)
481			s.recompute()
482			return
483		}
484		w := ws[0]
485		for _, x := range ws[1:] {
486			if s.eff[x] < s.eff[w] ||
487				(s.eff[x] == s.eff[w] && s.blockTime[x] < s.blockTime[w]) ||
488				(s.eff[x] == s.eff[w] && s.blockTime[x] == s.blockTime[w] && x < w) {
489				w = x
490			}
491		}
492		s.owner[m] = w
493		s.locksOf[w][m] = true
494		remaining := make([]int, 0, len(ws)-1)
495		for _, x := range ws {
496			if x != w {
497				remaining = append(remaining, x)
498			}
499		}
500		s.waiters[m] = remaining
501		s.blockedM[w] = ""
502		s.recompute()
503	}
504	
505	// recompute derives every effective priority as the minimum of the task's own
506	// priority and the effective priorities of the direct waiters on its mutexes;
507	// the DFS therefore covers indirect inheritance transitively.
508	func (s *mutexSim) recompute() {
509		mark := make([]int8, s.n)
510		var dfs func(int) int64
511		dfs = func(i int) int64 {
512			if mark[i] == 2 {
513				return s.eff[i]
514			}
515			mark[i] = 1
516			best := s.tasks[i].priority
517			for _, w := range s.waitersOn(i) {
518				if v := dfs(w); v < best {
519					best = v
520				}
521			}
522			mark[i] = 2
523			s.eff[i] = best
524			return best
525		}
526		for i := 0; i < s.n; i++ {
527			dfs(i)
528		}
529	}
530	
531	// pickBest selects the runnable task with the highest effective priority,
532	// breaking ties by release time then input index.
533	func (s *mutexSim) pickBest() int {
534		best := -1
535		for i := 0; i < s.n; i++ {
536			if !s.released[i] || s.completed[i] || s.blockedM[i] != "" {
537				continue
538			}
539			if best == -1 {
540				best = i
541				continue
542			}
543			a, b := s.tasks[i], s.tasks[best]
544			if s.eff[i] < s.eff[best] ||
545				(s.eff[i] == s.eff[best] && a.release < b.release) ||
546				(s.eff[i] == s.eff[best] && a.release == b.release && i < best) {
547				best = i
548			}
549		}
550		return best
551	}
552	
553	func (s *mutexSim) runnable(i int) bool {
554		return s.released[i] && !s.completed[i] && s.blockedM[i] == "" && s.runRem[i] > 0
555	}
556	
557	func (s *mutexSim) releaseUpTo() {
558		for s.nextRel < s.n && s.tasks[s.order[s.nextRel]].release <= s.now {
559			s.released[s.order[s.nextRel]] = true
560			s.nextRel++
561		}
562	}
563	
564	func (s *mutexSim) buildResponse(deadlocked bool) mutexResponse {
565		timeline := make([]mutexTimelineInterval, 0, len(s.segs))
566		for _, seg := range s.segs {
567			last := len(timeline) - 1
568			if last >= 0 &&
569				timeline[last].TaskID == s.tasks[seg.index].id &&
570				timeline[last].EffectivePriority == seg.eff &&
571				timeline[last].End == seg.start {
572				timeline[last].End = seg.end
573				continue
574			}
575			timeline = append(timeline, mutexTimelineInterval{
576				TaskID:            s.tasks[seg.index].id,
577				Start:             seg.start,
578				End:               seg.end,
579				EffectivePriority: seg.eff,
580			})
581		}
582	
583		results := make([]mutexTaskResult, s.n)
584		allCompleted := true
585		for i, t := range s.tasks {
586			state := "ready"
587			switch {
588			case s.completed[i]:
589				state = "completed"
590			case s.blockedM[i] != "":
591				state = "blocked"
592			case !s.released[i]:
593				state = "unreleased"
594			}
595			if state != "completed" {
596				allCompleted = false
597			}
598			var blockedOn *string
599			if state == "blocked" {
600				m := s.blockedM[i]
601				blockedOn = &m
602			}
603			var deadlineStatus string
604			switch c := s.completion[i]; {
605			case c != nil && *c <= t.deadline:
606				deadlineStatus = "met"
607			case c != nil:
608				deadlineStatus = "missed"
609			case t.deadline <= s.horizon:
610				deadlineStatus = "missed"
611			default:
612				deadlineStatus = "pending"
613			}
614			results[i] = mutexTaskResult{
615				Executed:       s.executed[i],
616				Completion:     s.completion[i],
617				State:          state,
618				BlockedOn:      blockedOn,
619				DeadlineStatus: deadlineStatus,
620			}
621		}
622	
623		status := "horizon"
624		if deadlocked {
625			status = "deadlocked"
626		} else if allCompleted {
627			status = "completed"
628		}
629	
630		resp := mutexResponse{
631			Status:   status,
632			Timeline: timeline,
633			Results:  results,
634		}
635		if deadlocked {
636			at := s.now
637			resp.DeadlockAt = &at
638			cycle := make([]string, len(s.deadCycle))
639			for k, idx := range s.deadCycle {
640				cycle[k] = s.tasks[idx].id
641			}
642			resp.Cycle = cycle
643		}
644		return resp
645	}
