	}

	// Unknown JSON keys and syntax defects stay 400.
	bad400 := map[string]string{
		"unknown key":     base(good)[:len(base(good))-1] + `,"bogus":1}`,
		"trailing token":  base(good) + ` garbage`,
		"duplicate key":   `{"horizon":3,"horizon":4,"tasks":[` + good + `]}`,
		"syntax error":    `{`,
		"unknown action":  base(mtask("a", 0, 0, 20, `{"sleep":1}`)),
	}
	for name, body := range bad400 {
		t.Run(name, func(t *testing.T) {
			assertErrorCode(t, postMutex(t, body, "application/json"),
				http.StatusBadRequest, "invalid_json")
		})
	}

	// 1024 actions accepted; 1025 rejected. Construct a balanced program.
	var acts []string
	for i := 0; i < 512; i++ {
		acts = append(acts, mlock("M"+strconv.Itoa(i)))
	}
	for i := 511; i >= 0; i-- {
		acts = append(acts, munlock("M"+strconv.Itoa(i)))
	}
	mutexOK(t, base(mtask("a", 0, 0, 20, acts...)))
	acts = append(acts, mrun(1), mrun(1)) // needs balance: instead build 1025 balanced? length 1024 already max
	_ = acts
}

func TestMutexActionCountBounds(t *testing.T) {
	mk := func(count int) string {
		var acts []string
		// All-lock/unlock balanced programs of exactly `count` actions require
		// even counts; pad with run pairs, every program just needs length.
		for i := 0; i < count; i++ {
			if i%2 == 0 {
				acts = append(acts, mrun(1))
			} else {
				acts = append(acts, mrun(2))
			}
		}
		return `{"horizon":100000,"tasks":[` + mtask("a", 0, 0, 200000, acts...) + `]}`
	}
	rec := postMutex(t, mk(1025), "application/json")
	assertErrorCode(t, rec, http.StatusUnprocessableEntity, "validation_failed")
}

func TestMutexMethodAndMediaType(t *testing.T) {
	for _, method := range []string{http.MethodGet, http.MethodPut, http.MethodDelete, http.MethodPatch} {
		rec := httptest.NewRecorder()
		Handler().ServeHTTP(rec, httptest.NewRequest(method, mutexAnalyzePath, nil))
		assertErrorCode(t, rec, http.StatusMethodNotAllowed, "method_not_allowed")
		if got := rec.Header().Get("Allow"); got != http.MethodPost {
			t.Fatalf("Allow = %q, want POST", got)
		}
	}
	assertErrorCode(t, postMutex(t, `{"horizon":3,"tasks":[]}`, ""),
		http.StatusUnsupportedMediaType, "unsupported_media_type")
	assertErrorCode(t, postMutex(t, `{"horizon":3,"tasks":[]}`, "text/plain"),
		http.StatusUnsupportedMediaType, "unsupported_media_type")
	rec := postMutex(t, `{"horizon":3,"tasks":[`+
		mtask("a", 0, 0, 20, mrun(1))+`]}`, "application/json; charset=utf-8")
	if rec.Code != http.StatusOK {
		t.Fatalf("charset parameter rejected: %d %s", rec.Code, rec.Body.String())
	}
}

// ---- Differential test against an independent tick-by-tick reference ------

type refTask struct {
	prio, release, deadline int64
	acts                    []mutexAction
}

type refSim struct {
	tasks   []refTask
	n       int
	horizon int64

	owner     map[string]int
	waiters   map[string][]int
	held      []map[string]bool
	blockedM  []string
	blockTime []int64
	pc        []int
	rem       []int64
	released  []bool
	done      []bool
	executed  []int64
	finish    []*int64
	eff       []int64
	now       int64
	current   int
	segs      []mutexSegment
	dead      bool
	deadAt    int64
	cycle     []int
}

func refRun(tasks []refTask, horizon int64) (status string, tl []mutexTimelineInterval, res []mutexTaskResult, deadAt *int64, cycle []string) {
	r := &refSim{
		tasks: tasks, n: len(tasks), horizon: horizon,
		owner: map[string]int{}, waiters: map[string][]int{},
		current: -1,
	}
	r.held = make([]map[string]bool, r.n)
	r.blockedM = make([]string, r.n)
	r.blockTime = make([]int64, r.n)
	r.pc = make([]int, r.n)
	r.rem = make([]int64, r.n)
	r.released = make([]bool, r.n)
	r.done = make([]bool, r.n)
	r.executed = make([]int64, r.n)
	r.finish = make([]*int64, r.n)
	r.eff = make([]int64, r.n)
	for i := range tasks {
		r.held[i] = map[string]bool{}
		r.eff[i] = tasks[i].prio
	}

	for t := int64(0); t < horizon; t++ {
		r.now = t
		for i := 0; i < r.n; i++ {
			if tasks[i].release == t {
				r.released[i] = true
			}
		}
		if !r.settlePoint() {
			break
		}
		if r.current == -1 {
			continue
		}
		cur := r.current
		// One tick of execution.
		r.rem[cur]--
		r.executed[cur]++
		r.segs = append(r.segs, mutexSegment{index: cur, start: t, end: t + 1, eff: r.eff[cur]})
		if r.rem[cur] == 0 {
			r.pc[cur]++
			r.current = -1
		}
	}

	// Boundary instant at t == horizon: drain the just-finished current task's
	// zero-duration chain once (matches the boundary rule).
	if r.current == -1 && len(r.segs) > 0 {
		last := r.segs[len(r.segs)-1]
		if last.end == horizon {
			i := last.index
			if !r.done[i] && r.blockedM[i] == "" && r.pc[i] < len(tasks[i].acts) {
				r.current = i
				r.now = horizon
				if r.settle(i) {
					r.dead = true
					r.deadAt = horizon
				}
				r.current = -1
			}
		}
	}

	return r.build()
}

// settlePoint performs all zero-time resolution at the current instant and
// leaves r.current on the task that owns the CPU going forward.
func (r *refSim) settlePoint() bool {
	for {
		// The current task drains first.
		if r.current != -1 {
			if r.settle(r.current) {
				r.markDead()
				return false
			}
			if r.done[r.current] || r.blockedM[r.current] != "" {
				r.current = -1
			} else if r.rem[r.current] == 0 {
				r.current = -1
			}
		}
		best := r.pick()
		if r.current == -1 {
			if best == -1 {
				return true
			}
			r.current = best
			if r.settle(best) {
				r.markDead()
				return false
			}
			if r.done[best] || r.blockedM[best] != "" {
				r.current = -1
				continue
			}
			if r.rem[best] == 0 {
				r.current = -1
				continue
			}
			return true
		}
		if best != -1 && r.eff[best] < r.eff[r.current] {
			r.current = best
			if r.settle(best) {
				r.markDead()
				return false
			}
			if r.done[best] || r.blockedM[best] != "" || r.rem[best] == 0 {
				r.current = -1
				continue
			}
		}
		return true
	}
}

func (r *refSim) settle(i int) bool {
	tk := r.tasks[i]
	for r.pc[i] < len(tk.acts) {
		a := tk.acts[r.pc[i]]
		switch a.kind {
		case mutexActRun:
			if r.rem[i] == 0 {
				r.rem[i] = a.run
			}
			return false
		case mutexActLock:
			if owner, ok := r.owner[a.name]; ok {
				if owner == i {
					r.pc[i]++
					continue
				}
				cycle := r.findCycle(i, owner)
				r.blockedM[i] = a.name
				r.blockTime[i] = r.now
				r.waiters[a.name] = append(r.waiters[a.name], i)
				if cycle != nil {
					r.cycle = cycle
					return true
				}
				r.recompute()
				return false
			}
			r.owner[a.name] = i
			r.held[i][a.name] = true
			r.pc[i]++
		case mutexActUnlock:
			r.give(a.name, i)
			r.pc[i]++
		}
	}
	r.done[i] = true
	at := r.now
	r.finish[i] = &at
	return false
}

func (r *refSim) findCycle(waiter, holder int) []int {
	chain := []int{holder}
	cur := holder
	for {
		if r.blockedM[cur] == "" {
			return nil
		}
		next := r.owner[r.blockedM[cur]]
		if next == waiter {
			break
		}
		chain = append(chain, next)
		cur = next
	}
	cycle := append([]int{waiter}, chain...)
	first := 0
	for k := 1; k < len(cycle); k++ {
		if cycle[k] < cycle[first] {
			first = k
		}
	}
	return append(append([]int(nil), cycle[first:]...), cycle[:first]...)
}

func (r *refSim) markDead() {
	r.dead = true
	r.deadAt = r.now
}

func (r *refSim) give(m string, from int) {
	ws := r.waiters[m]
	delete(r.held[from], m)
	if len(ws) == 0 {
		delete(r.owner, m)
		r.recompute()
		return
	}
	w := ws[0]
	for _, x := range ws[1:] {
		if r.eff[x] < r.eff[w] ||
			(r.eff[x] == r.eff[w] && r.blockTime[x] < r.blockTime[w]) ||
			(r.eff[x] == r.eff[w] && r.blockTime[x] == r.blockTime[w] && x < w) {
			w = x
		}
	}
	r.owner[m] = w
	r.held[w][m] = true
	var rest []int
	for _, x := range ws {
		if x != w {
			rest = append(rest, x)
		}
	}
	r.waiters[m] = rest
	r.blockedM[w] = ""
	r.recompute()
}

func (r *refSim) recompute() {
	color := make([]int, r.n)
	var walk func(int) int64
	walk = func(i int) int64 {
		if color[i] == 2 {
			return r.eff[i]
		}
		color[i] = 1
		best := r.tasks[i].prio
		for m := range r.held[i] {
			for _, w := range r.waiters[m] {
				if v := walk(w); v < best {
					best = v
				}
			}
		}
		color[i] = 2
		r.eff[i] = best
		return best
	}
	for i := 0; i < r.n; i++ {
		walk(i)
	}
}

func (r *refSim) pick() int {
	best := -1
	for i := 0; i < r.n; i++ {
		if !r.released[i] || r.done[i] || r.blockedM[i] != "" {
			continue
		}
		if best == -1 {
			best = i
			continue
		}
		a, b := r.tasks[i], r.tasks[best]
		if r.eff[i] < r.eff[best] ||
			(r.eff[i] == r.eff[best] && a.release < b.release) ||
			(r.eff[i] == r.eff[best] && a.release == b.release && i < best) {
			best = i
		}
	}
	return best
}

func (r *refSim) build() (string, []mutexTimelineInterval, []mutexTaskResult, *int64, []string) {
	tl := make([]mutexTimelineInterval, 0)
	for _, seg := range r.segs {
		last := len(tl) - 1
		if last >= 0 && tl[last].TaskID == r.tasks[seg.index].acts[0].kind.kindString() && false {
		}
		if last >= 0 &&
			tl[last].TaskID == r.taskID(seg.index) &&
			tl[last].EffectivePriority == seg.eff &&
			tl[last].End == seg.start {
			tl[last].End = seg.end
			continue
		}
		tl = append(tl, mutexTimelineInterval{
			TaskID: r.taskID(seg.index), Start: seg.start, End: seg.end, EffectivePriority: seg.eff,
		})
	}
	res := make([]mutexTaskResult, r.n)
	allDone := true
	for i, tk := range r.tasks {
		state := "ready"
		switch {
		case r.done[i]:
			state = "completed"
		case r.blockedM[i] != "":
			state = "blocked"
		case !r.released[i]:
			state = "unreleased"
		}
		if state != "completed" {
			allDone = false
		}
		var bo *string
		if state == "blocked" {
			m := r.blockedM[i]
			bo = &m
		}
		var ds string
		switch c := r.finish[i]; {
		case c != nil && *c <= tk.deadline:
			ds = "met"
		case c != nil:
			ds = "missed"
		case tk.deadline <= r.horizon:
			ds = "missed"
		default:
			ds = "pending"
		}
		res[i] = mutexTaskResult{
			Executed: r.executed[i], Completion: r.finish[i],
			State: state, BlockedOn: bo, DeadlineStatus: ds,
		}
	}
	status := "horizon"
	switch {
	case r.dead:
		status = "deadlocked"
	case allDone:
		status = "completed"
	}
	var at *int64
	var cyc []string
	if r.dead {
		v := r.deadAt
		at = &v
		for _, idx := range r.cycle {
			cyc = append(cyc, r.taskID(idx))
		}
	}
	return status, tl, res, at, cyc
}

func (r *refSim) taskID(i int) string {
	return r.tasks[i].acts[0].name + idFor(r.tasks[i])
}

func idFor(t refTask) string {
	// Stable id from properties is awkward; instead rely on field set below.
	return t.idTail
}

func TestMutexDifferential(t *testing.T) {
	seed := time.Now().UnixNano()
	rng := rand.New(rand.NewSource(seed))
	for iter := 0; iter < 1500; iter++ {
		n := 1 + rng.Intn(5)
		horizon := int64(2 + rng.Intn(24))
		names := []string{"m0", "m1", "m2"}

		genTasks := func() ([]mutexTask, []refTask, []string) {
			got := make([]mutexTask, n)
			ref := make([]refTask, n)
			ids := make([]string, n)
			used := map[string]bool{}
			for i := 0; i < n; i++ {
				var id string
				for {
					id = "t" + strconv.Itoa(rng.Intn(40))
					if !used[id] {
						used[id] = true
						break
					}
				}
				ids[i] = id
				prio := int64(rng.Intn(4))
				rel := int64(rng.Intn(int(horizon)))
				dead := rel + int64(1+rng.Intn(30))
				nacts := 1 + rng.Intn(8)
				acts := make([]mutexAction, 0, nacts)
				var open []string
				for k := 0; k < nacts; k++ {
					choice := rng.Intn(10)
					if choice < 6 {
						acts = append(acts, mutexAction{kind: mutexActRun, run: int64(1 + rng.Intn(5))})
					} else if choice < 8 {
						m := names[rng.Intn(len(names))]
						held := false
						for _, h := range open {
							if h == m {
								held = true
							}
						}
						if held {
							acts = append(acts, mutexAction{kind: mutexActRun, run: 1})
						} else {
							acts = append(acts, mutexAction{kind: mutexActLock, name: m})
							open = append(open, m)
						}
					} else {
						if len(open) == 0 {
							acts = append(acts, mutexAction{kind: mutexActRun, run: 1})
						} else {
							j := rng.Intn(len(open))
							m := open[j]
							open = append(open[:j], open[j+1:]...)
							acts = append(acts, mutexAction{kind: mutexActUnlock, name: m})
						}
					}
				}
				// Close in reverse acquisition order (valid nesting, but any
				// order is valid as long as held).
				for j := len(open) - 1; j >= 0; j-- {
					acts = append(acts, mutexAction{kind: mutexActUnlock, name: open[j]})
				}
				got[i] = mutexTask{id: id, priority: prio, release: rel, deadline: dead, actions: acts}
				ref[i] = refTask{prio: prio, release: rel, deadline: dead, acts: acts, idTail: id}
			}
			return got, ref, ids
		}

		got, ref, ids := genTasks()
		resp := simulateMutex(got, horizon)
		rStatus, rTL, rRes, rAt, rCycle := refRun(ref, horizon)

		if resp.Status != rStatus {
			t.Fatalf("iter %d seed %d: status %q vs %q; got tl %+v", iter, seed, resp.Status, rStatus, resp.Timeline)
		}
		if len(resp.Timeline) != len(rTL) {
			t.Fatalf("iter %d seed %d: timeline len %d vs %d\ngot %+v\nref %+v",
				iter, seed, len(resp.Timeline), len(rTL), resp.Timeline, rTL)
		}
		for k := range rTL {
			if resp.Timeline[k] != rTL[k] {
				t.Fatalf("iter %d seed %d: tl[%d] %+v vs %+v", iter, seed, k, resp.Timeline[k], rTL[k])
			}
		}
		for i := range rRes {
			g, rr := resp.Results[i], rRes[i]
			if g.Executed != rr.Executed || g.State != rr.State || g.DeadlineStatus != rr.DeadlineStatus {
				t.Fatalf("iter %d seed %d: %s result %+v vs %+v", iter, seed, ids[i], g, rr)
			}
			if (g.Completion == nil) != (rr.Completion == nil) ||
				(g.Completion != nil && *g.Completion != *rr.Completion) {
				t.Fatalf("iter %d seed %d: %s completion %v vs %v", iter, seed, ids[i], g.Completion, rr.Completion)
			}
			if (g.BlockedOn == nil) != (rr.BlockedOn == nil) ||
				(g.BlockedOn != nil && *g.BlockedOn != *rr.BlockedOn) {
				t.Fatalf("iter %d seed %d: %s blockedOn %v vs %v", iter, seed, ids[i], g.BlockedOn, rr.BlockedOn)
			}
		}
		if (resp.DeadlockAt == nil) != (rAt == nil) ||
			(resp.DeadlockAt != nil && *resp.DeadlockAt != *rAt) {
			t.Fatalf("iter %d seed %d: deadlockAt %v vs %v", iter, seed, resp.DeadlockAt, rAt)
		}
		if strings.Join(resp.Cycle, ",") != strings.Join(rCycle, ",") {
			t.Fatalf("iter %d seed %d: cycle %v vs %v", iter, seed, resp.Cycle, rCycle)
		}
	}
}

