func mutexOK(t *testing.T, body string) mutexResponse {
	t.Helper()
	rec := postMutex(t, body, "application/json")
	if rec.Code != http.StatusOK {
		t.Fatalf("status = %d, want 200; body: %s", rec.Code, rec.Body.String())
