		"empty actions":        base(mtask("a", 0, 0, 20)),
		"no verb":              base(mtask("a", 0, 0, 20, `{}`)),
		"two verbs":            base(mtask("a", 0, 0, 20, `{"run":1,"lock":"M"}`)),
		"run zero":             base(mtask("a", 0, 0, 20, mrun(0))),
		"run negative":         base(mtask("a", 0, 0, 20, `{"run":-1}`)),
